function helio_sat(T){
var L=VSOP_sat_L0(T)+VSOP_sat_L1(T)*T+VSOP_sat_L2(T)*T*T+VSOP_sat_L3(T)*T*T*T+VSOP_sat_L4(T)*T*T*T*T+VSOP_sat_L5(T)*T*T*T*T*T;
var B=VSOP_sat_B0(T)+VSOP_sat_B1(T)*T+VSOP_sat_B2(T)*T*T+VSOP_sat_B3(T)*T*T*T+VSOP_sat_B4(T)*T*T*T*T+VSOP_sat_B5(T)*T*T*T*T*T;
var R=VSOP_sat_R0(T)+VSOP_sat_R1(T)*T+VSOP_sat_R2(T)*T*T+VSOP_sat_R3(T)*T*T*T+VSOP_sat_R4(T)*T*T*T*T+VSOP_sat_R5(T)*T*T*T*T*T;
return {L:L,B:B,R:R};}


function lahiriAyanamsha(Tcy) {
  // Tcy in centuries
  return 23.857092 + (5028.796195*Tcy + 1.1054348*Tcy*Tcy)/3600.0;
}
function helio(pname, Tmill) {
  if (pname==='mer') return helio_mer(Tmill);
  if (pname==='ven') return helio_ven(Tmill);
  if (pname==='ear') return helio_ear(Tmill);
  if (pname==='mar') return helio_mar(Tmill);
  if (pname==='jup') return helio_jup(Tmill);
  if (pname==='sat') return helio_sat(Tmill);
}
function planetSidereal(pname, jd_utc) {
  var Tmill = (jd_utc - 2451545.0)/365250.0;
  var Tcy = Tmill*10.0;
  var hp = helio(pname, Tmill);
  var he = helio('ear', Tmill);
  var xp = hp.R*Math.cos(hp.B)*Math.cos(hp.L);
  var yp = hp.R*Math.cos(hp.B)*Math.sin(hp.L);
  var zp = hp.R*Math.sin(hp.B);
  var xe = he.R*Math.cos(he.B)*Math.cos(he.L);
  var ye = he.R*Math.cos(he.B)*Math.sin(he.L);
  var ze = he.R*Math.sin(he.B);
  var x = xp - xe, y = yp - ye;
  var lon_trop = Math.atan2(y, x) * 180/Math.PI;
  if (lon_trop < 0) lon_trop += 360;
  var sid = lon_trop - lahiriAyanamsha(Tcy);
  sid = sid % 360; if (sid < 0) sid += 360;
  return sid;
}
function sunSidereal(jd_utc) {
  var Tmill = (jd_utc - 2451545.0)/365250.0;
  var Tcy = Tmill*10.0;
  var he = helio_ear(Tmill);
  var xe = he.R*Math.cos(he.B)*Math.cos(he.L);
  var ye = he.R*Math.cos(he.B)*Math.sin(he.L);
  var lon_trop = Math.atan2(-ye, -xe) * 180/Math.PI;
  if (lon_trop < 0) lon_trop += 360;
  lon_trop -= 20.496/3600.0; // stellar aberration (constant of aberration), matches Swiss apparent place
  var sid = lon_trop - lahiriAyanamsha(Tcy);
  sid = sid % 360; if (sid < 0) sid += 360;
  return sid;
}


/* Mean lunar node (tropical, degrees), T in centuries from J2000 */
function meanNodeTropical(T) {
  return 125.04452 - 1934.136261*T + 0.0020708*T*T + (T*T*T)/450000.0;
}
function rahuSidereal(jd_utc) {
  var T = (jd_utc - 2451545.0)/36525.0;
  var trop = meanNodeTropical(T) % 360.0;
  if (trop < 0) trop += 360.0;
  var sid = trop - lahiriAyanamsha(T);
  sid = sid % 360.0; if (sid < 0) sid += 360.0;
  return sid;
}
function ketuSidereal(jd_utc) {
  return (rahuSidereal(jd_utc) + 180.0) % 360.0;
}

/* Ascendant (sidereal, degrees) */
function ascendantSidereal(jd_utc, lat_deg, lon_deg_east) {
  var T = (jd_utc - 2451545.0)/36525.0;
  // GMST (degrees)
  var gmst = (280.46061837 + 360.98564736629*(jd_utc - 2451545.0) + 0.000387933*T*T - (T*T*T)/38710000.0) % 360.0;
  if (gmst < 0) gmst += 360.0;
  var lst_deg = (gmst + lon_deg_east) % 360.0;
  var LST = lst_deg * Math.PI/180.0;
  var phi = lat_deg * Math.PI/180.0;
  // Mean obliquity (degrees -> radians)
  var eps_deg = 23.4392911 - 0.0130042*T - 0.00000164*T*T + 0.000000504*T*T*T;
  var eps = eps_deg * Math.PI/180.0;
  // Ascendant (tropical)
  var y = Math.cos(LST);
  var x = -(Math.sin(LST)*Math.cos(eps) + Math.tan(phi)*Math.sin(eps));
  var asc_trop = Math.atan2(y, x) * 180.0/Math.PI;
  if (asc_trop < 0) asc_trop += 360.0;
  // Convert to sidereal
  var sid = asc_trop - lahiriAyanamsha(T);
  sid = sid % 360.0; if (sid < 0) sid += 360.0;
  return sid;
}

/* Main API: compute all positions for a Julian Day (UTC) */
function computeKundali(jd_utc, lat_deg, lon_deg_east) {
  return {
    ascendant: ascendantSidereal(jd_utc, lat_deg, lon_deg_east),
    sun: sunSidereal(jd_utc),
    moon: moonSiderealLongitude(jd_utc),
    mars: planetSidereal('mar', jd_utc),
    mercury: planetSidereal('mer', jd_utc),
    jupiter: planetSidereal('jup', jd_utc),
    venus: planetSidereal('ven', jd_utc),
    saturn: planetSidereal('sat', jd_utc),
    rahu: rahuSidereal(jd_utc),
    ketu: ketuSidereal(jd_utc)
  };
}
